+        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");
+
+var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";
+
+builder.Services.AddChatClient(b => b
+    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));
+
+builder.Services.AddSingleton<NoteService>();
+
+var host = builder.Build();
+
+var chatClient = host.Services.GetRequiredService<IChatClient>();
+var noteService = host.Services.GetRequiredService<NoteService>();
+
+// Define tools available to the agent
+var searchTool = AIFunctionFactory.Create(WebSearchTool.SearchWeb);
+var addNoteTool = AIFunctionFactory.Create(noteService.AddNote);
+var getNotesTool = AIFunctionFactory.Create(noteService.GetNotes);
+
+// Create the agent with tools
+var agent = new ChatClientAgent(chatClient,
+    new ChatClientAgentOptions
+    {
+        Instructions = """
+            You are a research agent. Your job is to research a topic thoroughly by:
+            1. Searching the web for relevant information using the search tool.
+            2. Taking notes on key findings using the note-taking tool.
+            3. Performing multiple searches to cover different aspects of the topic.
+            4. After gathering enough information, retrieve your notes and provide a 
+               comprehensive summary of your findings.
+
+            Always take notes on important facts before moving to the next search.
+            When you have enough information (at least 3 searches), summarize everything.
+            """,
+        Tools = [searchTool, addNoteTool, getNotesTool],
+        DefaultOptions = new ChatOptions
+        {
+            Temperature = 0f,
+            MaxOutputTokens = 2048,
+        },
+    });
+
+// Get topic from user
+Console.Write("Enter a research topic: ");
+var topic = Console.ReadLine()?.Trim();
+if (string.IsNullOrEmpty(topic))
+{
+    Console.WriteLine("No topic provided. Exiting.");
+    return;
+}
+
+Console.WriteLine($"\nResearching: {topic}\n");
+Console.WriteLine(new string('-', 50));
+
+// Run the agent
+var history = new List<ChatMessage>
+{
+    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
+};
+
+var invokeOptions = new AgentInvokeOptions
+{
+    MaximumIterations = 10,
+};
+
+await foreach (var message in agent.InvokeStreamingAsync(history, invokeOptions))
+{
+    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
+    {
+        Console.Write(message.Text);
+    }
+}
+
+Console.WriteLine($"\n{new string('-', 50)}");
+Console.WriteLine($"\nNotes collected ({noteService.Count}):");
+foreach (var note in noteService.AllNotes)
+{
+    Console.WriteLine($"  • {note}");
+}
+
+// --- Tool Implementations ---
+
+/// <summary>Simulated web search tool that returns results for a query.</summary>
+static class WebSearchTool
+{
+    [Description("Searches the web for information on a given query and returns relevant results.")]
+    public static string SearchWeb(
+        [Description("The search query to look up")] string query)
+    {
+        // In production, replace with a real search API (Bing Search, Google Custom Search, etc.)
+        // This simulation demonstrates the agent's tool-calling behavior.
+        var results = new[]
+        {
+            $"[Search results for '{query}']",
+            $"Result 1: Found comprehensive overview of {query} from Wikipedia.",
+            $"Result 2: Recent news article discussing latest developments in {query}.",
+            $"Result 3: Academic paper analyzing key aspects of {query}.",
+            $"Summary: Multiple sources confirm that {query} is a multi-faceted topic with "
+                + "ongoing research and development. Key themes include innovation, "
+                + "practical applications, and future implications.",
+        };
+
+        Console.WriteLine($"  🔍 Searching: \"{query}\"");
+        return string.Join("\n", results);
+    }
+}
+
+/// <summary>Note-taking service that stores research findings.</summary>
+class NoteService
+{
+    private readonly List<string> _notes = [];
+
+    public IReadOnlyList<string> AllNotes => _notes;
+    public int Count => _notes.Count;
+
+    [Description("Saves a research note for later reference. Use this to record key findings.")]
+    public string AddNote(
+        [Description("The note content to save")] string note)
+    {
+        _notes.Add(note);
+        Console.WriteLine($"  📝 Note added: \"{note[..Math.Min(note.Length, 60)]}...\"");
+        return $"Note saved successfully. You now have {_notes.Count} note(s).";
+    }
+
+    [Description("Retrieves all saved research notes.")]
+    public string GetNotes()
+    {
+        if (_notes.Count == 0)
+            return "No notes saved yet.";
+
+        return $"Saved notes ({_notes.Count}):\n" +
+               string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
+    }
+}

